<script setup>
defineProps({ question: { type: Object, required: true }, selected: { type: [String, Number], default: '' }, locked: Boolean })
defineEmits(['select'])
</script>

<template>
  <section class="glass rounded-3xl p-6 sm:p-9"><div class="flex items-center justify-between"><span class="rounded-lg bg-indigo-400/10 px-3 py-1.5 text-xs font-bold uppercase tracking-wider text-indigo-200">{{ question.type.replace('-', ' ') }}</span><span class="text-xs font-semibold text-slate-500">Choose one answer</span></div><h2 class="mt-8 text-2xl font-bold leading-relaxed text-white sm:text-3xl">{{ question.prompt }}</h2><div v-if="question.options" class="mt-8 grid gap-3"><button v-for="(option, index) in question.options" :key="option" :disabled="locked" class="flex items-center gap-4 rounded-xl border border-white/10 bg-white/[.03] p-4 text-left text-sm font-semibold text-slate-300 transition hover:border-cyan-300/40 hover:bg-cyan-300/5 disabled:cursor-default" :class="{ 'border-cyan-300/60 bg-cyan-300/10 text-cyan-100': selected === option, 'border-emerald-400/60 bg-emerald-400/10 text-emerald-100': locked && selected === option && selected.toLowerCase() === question.answer.toLowerCase(), 'border-red-400/60 bg-red-400/10 text-red-100': locked && selected === option && selected.toLowerCase() !== question.answer.toLowerCase() }" @click="$emit('select', option)"><span class="grid h-8 w-8 shrink-0 place-items-center rounded-lg bg-white/10 text-xs text-slate-400">{{ String.fromCharCode(65 + index) }}</span>{{ option }}</button></div><input v-else :value="selected" :disabled="locked" :placeholder="question.type === 'fill-blank' ? 'Complete the sentence...' : 'Type your answer...'" class="mt-8 w-full rounded-xl border border-white/10 bg-white/5 px-4 py-4 text-white outline-none placeholder:text-slate-600 focus:border-cyan-300/60" @input="$emit('select', $event.target.value)" /></section>
</template>